bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 - <<'PY'
import json,subprocess,sys
r=subprocess.run(["python3","scripts/userbot_topic_audit_client.py","--chat-id","-1002373696859","--topic-id","1"],capture_output=True,text=True,timeout=125)
if r.returncode:sys.exit(60)
a=[json.loads(z.split("=",1)[1]) for z in r.stdout.splitlines() if z.startswith("USERBOT_TOPIC_AUDIT=")]
if len(a)!=1 or len(a[0].get("rows",[]))!=1:sys.exit(61)
row=a[0]["rows"][0]
if row.get("topic_id")!=1:sys.exit(62)
migration=row.get("migration") or {}
if migration.get("message_id")!=4703 or migration.get("transport")!="NOT_FOUND":sys.exit(63)
post=row.get("post_button")
pin=row.get("pin_state")
if post=="PRESENT" and pin=="PRESENT":sys.exit(80)
if post=="PRESENT":sys.exit(81)
if post=="ABSENT" and pin=="ABSENT_FROM_PINS":sys.exit(82)
sys.exit(83)
PY
